from pathlib import Path

path=Path('src/modules/engineering/ui/GuidedMeasurementFlow.tsx')
text=path.read_text(encoding='utf-8')

text=text.replace("import { useEngineeringOperations } from './useEngineeringOperations';", "import { useEngineeringOperations } from './useEngineeringOperations';\nimport { loadContractRetentions } from '../infrastructure/EngineeringContractModalRepository';")

text=text.replace("  const [,setFinished]=useState(false);\n  const operations=useEngineeringOperations(scope);", "  const [,setFinished]=useState(false);\n  const [retentions,setRetentions]=useState({inss:0,iss:0,rt:0});\n  const operations=useEngineeringOperations(scope);")

text=text.replace("  useEffect(()=>{void reload();},[reload]);", "  useEffect(()=>{void reload();},[reload]);\n  useEffect(()=>{void loadContractRetentions(scope,contractId).then(setRetentions).catch(()=>setRetentions({inss:0,iss:0,rt:0}));},[scope,contractId]);")

anchor="""  const summary=useMemo(()=>{\n    if(!model||!origin)return {contracted:0,previousMeasured:0,currentMeasurement:0,balance:0,currentPct:0,balancePct:0};"""
if anchor not in text:
    raise SystemExit('summary anchor not found')

insert="""  const stagePriceByTarget=useMemo(()=>{const map=new Map<string,number>();for(const itemOrigin of model?.origins??[])for(const item of itemOrigin.services)map.set(`${item.targetKind}:${item.targetId}`,item.unitPrice);return map;},[model]);\n  const measurementGross=useMemo(()=>{if(!model||!measurementId)return 0;return model.lines.filter(line=>line.measurementId===measurementId).reduce((sum,line)=>sum+line.measuredQuantity*(stagePriceByTarget.get(`${line.targetKind}:${line.targetId}`)??0),0);},[model,measurementId,stagePriceByTarget]);\n  const inssValue=measurementGross*retentions.inss/100;\n  const issValue=measurementGross*retentions.iss/100;\n  const rtValue=measurementGross*retentions.rt/100;\n  const measurementNet=Math.max(0,measurementGross-inssValue-issValue-rtValue);\n  const originRows=useMemo(()=>{if(!model||!measurementId)return [];return model.origins.map(itemOrigin=>{const keys=new Set(itemOrigin.services.map(item=>`${item.targetKind}:${item.targetId}`));const lines=model.lines.filter(line=>line.measurementId===measurementId&&keys.has(`${line.targetKind}:${line.targetId}`));const gross=lines.reduce((sum,line)=>sum+line.measuredQuantity*(stagePriceByTarget.get(`${line.targetKind}:${line.targetId}`)??0),0);const serviceCount=new Set(lines.map(line=>`${line.targetKind}:${line.targetId}`)).size;return {origin:itemOrigin,gross,serviceCount};}).filter(row=>row.serviceCount>0||row.gross>0);},[model,measurementId,stagePriceByTarget]);\n\n"""
text=text.replace(anchor,insert+anchor,1)

old="""      {(measurementId||draftMode)&&!originId&&<div className=\"guided-measurement__empty\"><strong>Selecione a torre ou aditivo</strong><span>Escolha abaixo a origem que deseja medir.</span><div className=\"guided-measurement__selectors\">{model.origins.map(item=><Button key={item.id} variant=\"secondary\" onClick={()=>chooseOrigin(item.id)}>{originLabel(item)}</Button>)}</div></div>}"""
new="""      {(measurementId||draftMode)&&!originId&&<div className=\"measurement-hub\">\n        <section className=\"approved-measurement-sheet__header-fields\">\n          <div><span>Nº da medição</span><strong>{draftHeader?.measurementNumber||draftMeasurements.find(item=>item.id===measurementId)?.measurementNumber||'—'}</strong></div>\n          <div><span>Competência</span><strong>{draftHeader?.competence||draftMeasurements.find(item=>item.id===measurementId)?.competence?.slice(0,7)||'—'}</strong></div>\n          <div><span>Vencimento previsto</span><strong>{draftHeader?.dueDate||'—'}</strong></div>\n          <div><span>Data prevista para pagamento</span><strong>{draftHeader?.expectedPaymentDate||'—'}</strong></div>\n          <div><span>Forma de pagamento</span><strong>{draftHeader?.paymentMethod||'PIX'}</strong></div>\n          <Button variant=\"secondary\">▣ Observações</Button>\n        </section>\n        <section className=\"measurement-hub__financial\">\n          <div><span>Bruto da medição</span><strong>{currency.format(measurementGross)}</strong></div>\n          <div><span>INSS ({retentions.inss.toLocaleString('pt-BR',{maximumFractionDigits:2})}%)</span><strong>{currency.format(inssValue)}</strong></div>\n          <div><span>ISS ({retentions.iss.toLocaleString('pt-BR',{maximumFractionDigits:2})}%)</span><strong>{currency.format(issValue)}</strong></div>\n          <div><span>Retenção ({retentions.rt.toLocaleString('pt-BR',{maximumFractionDigits:2})}%)</span><strong>{currency.format(rtValue)}</strong></div>\n          <div className=\"is-net\"><span>Líquido da medição</span><strong>{currency.format(measurementNet)}</strong></div>\n        </section>\n        <section className=\"measurement-hub__origin-picker\">\n          <div><strong>Selecionar origem</strong><span>Escolha a torre ou aditivo para lançar os serviços desta medição.</span></div>\n          <Select label=\"Torre / Aditivo\" value=\"\" onChange={event=>chooseOrigin(event.target.value)} options={[{value:'',label:'Selecione uma torre ou aditivo…'},...model.origins.map(item=>({value:item.id,label:originLabel(item)}))]}/>\n        </section>\n        <section className=\"measurement-hub__origins\">\n          <header><div><strong>Origens já adicionadas nesta medição</strong><span>Salve uma origem e escolha a próxima sem sair da medição.</span></div></header>\n          {originRows.length===0?<div className=\"measurement-hub__empty\">Nenhuma torre ou aditivo lançado ainda.</div>:<div className=\"measurement-hub__origin-list\">{originRows.map(row=><button key={row.origin.id} type=\"button\" onClick={()=>chooseOrigin(row.origin.id)}><span><strong>{originLabel(row.origin)}</strong><small>{row.serviceCount} serviço(s) lançado(s)</small></span><b>{currency.format(row.gross)}</b><em>Editar ›</em></button>)}</div>}\n        </section>\n        <footer className=\"approved-measurement-sheet__bottom-actions\"><Button variant=\"secondary\" onClick={closeFlow}>Cancelar medição</Button><div><Button variant=\"secondary\" onClick={onChanged}>▣ Salvar rascunho</Button><Button onClick={closeFlow}>✓ Finalizar medição</Button></div></footer>\n      </div>}"""
if old not in text:
    raise SystemExit('origin empty block not found')
text=text.replace(old,new,1)

old_footer="""        <footer className=\"approved-measurement-sheet__bottom-actions\"><Button variant=\"secondary\" onClick={closeFlow}>Cancelar medição</Button><div><Button variant=\"secondary\" disabled={saving||effectiveQuantity<=0} onClick={()=>void saveCurrent()}>{saving?'Salvando…':'▣ Salvar rascunho'}</Button><Button onClick={closeFlow}>✓ Finalizar medição</Button></div></footer>"""
new_footer="""        <footer className=\"approved-measurement-sheet__bottom-actions\"><Button variant=\"secondary\" onClick={()=>chooseOrigin('')}>← Voltar à medição</Button><div><Button variant=\"secondary\" disabled={saving||effectiveQuantity<=0} onClick={()=>void saveCurrent()}>{saving?'Salvando…':'▣ Salvar serviço'}</Button><Button onClick={()=>chooseOrigin('')}>✓ Salvar {originLabel(origin)}</Button></div></footer>"""
if old_footer not in text:
    raise SystemExit('footer block not found')
text=text.replace(old_footer,new_footer,1)

path.write_text(text,encoding='utf-8')

css=Path('src/modules/engineering/ui/guided-measurement-flow.css')
css_text=css.read_text(encoding='utf-8')
css_text += """\n/* Measurement hub - approved flow */\n.measurement-hub{display:grid;gap:16px;min-height:100%;align-content:start}.measurement-hub__financial{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.measurement-hub__financial>div{border:1px solid #dbe5ef;border-radius:16px;background:#fff;padding:14px 16px;display:grid;gap:5px;box-shadow:0 6px 18px rgba(15,23,42,.04)}.measurement-hub__financial span{font-size:.78rem;color:#64748b;font-weight:800}.measurement-hub__financial strong{font-size:1.18rem;color:#14243d}.measurement-hub__financial .is-net{background:#effcf5;border-color:#b9ebcf}.measurement-hub__financial .is-net strong{color:#138a50}.measurement-hub__origin-picker,.measurement-hub__origins{border:1px solid #dbe5ef;border-radius:18px;background:#fff;padding:18px;display:grid;gap:14px}.measurement-hub__origin-picker>div:first-child,.measurement-hub__origins header>div{display:grid;gap:4px}.measurement-hub__origin-picker span,.measurement-hub__origins header span{color:#64748b;font-size:.9rem}.measurement-hub__origin-list{display:grid;gap:9px}.measurement-hub__origin-list>button{width:100%;border:1px solid #dbe5ef;border-radius:14px;background:#fbfdff;padding:13px 15px;display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:14px;align-items:center;text-align:left;color:#15233b}.measurement-hub__origin-list>button:hover{border-color:#9ec5f6;background:#f4f9ff}.measurement-hub__origin-list>button>span{display:grid;gap:3px}.measurement-hub__origin-list small{color:#64748b}.measurement-hub__origin-list b{white-space:nowrap}.measurement-hub__origin-list em{font-style:normal;color:#1769d2;font-weight:800}.measurement-hub__empty{padding:18px;border:1px dashed #cbd5e1;border-radius:14px;color:#64748b;background:#f8fafc}@media(max-width:900px){.measurement-hub__financial{grid-template-columns:repeat(2,minmax(0,1fr))}.measurement-hub__financial .is-net{grid-column:1/-1}}@media(max-width:600px){.measurement-hub__financial{grid-template-columns:1fr}.measurement-hub__financial .is-net{grid-column:auto}.measurement-hub__origin-list>button{grid-template-columns:minmax(0,1fr) auto}.measurement-hub__origin-list em{display:none}}\n"""
css.write_text(css_text,encoding='utf-8')
print('patched measurement hub flow')
